// OrderService.proto
syntax = "proto3";
option csharp_namespace = "Orders";

service OrderService {
    rpc GetOrder (GetOrderRequest) returns (OrderResponse);
    rpc CreateOrder (CreateOrderRequest) returns (OrderResponse);
}

message GetOrderRequest { int32 id = 1; }
message OrderResponse { int32 id = 1; string status = 2; }

// Generated client usage
public class OrdersGrpcClient
{
    private readonly OrderService.OrderServiceClient _client;

    public OrdersGrpcClient(OrderService.OrderServiceClient client)
    {
        _client = client;
    }

    public async Task<OrderResponse> GetOrderAsync(int id)
    {
        return await _client.GetOrderAsync(new GetOrderRequest { Id = id });
    }
}

// Program.cs
builder.Services.AddGrpcClient<OrderService.OrderServiceClient>(options =>
    options.Address = new Uri("https://orders:5001"));

builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options =>
    {
        options.Authority = "https://identity.example.com";
        options.Audience = "gateway";
        options.TokenValidationParameters = new TokenValidationParameters
        {
            ValidateIssuer = true,
            ValidateAudience = true,
            ValidateLifetime = true,
            ValidateIssuerSigningKey = true
        };
    });

// Forward claims to downstream services
app.Use(async (context, next) =>
{
    if (context.User.Identity?.IsAuthenticated == true)
    {
        context.Request.Headers["X-User-Id"] = context.User.FindFirst("sub")?.Value ?? "";
        context.Request.Headers["X-User-Email"] = context.User.FindFirst("email")?.Value ?? "";
    }
    await next();
});
